/* Auth UI + explicit server adapter. No simulated accounts or browser-stored passwords. */
const authConfig = window.WEARQUEST_AUTH_CONFIG || {};
let authUser = null, authCsrf = '', authBusy = false, authBackend = 'firebase';
const authNames = {google:'구글',kakao:'카카오',naver:'네이버',apple:'Apple'};
function authBase(){return new URL(authConfig.apiBase,window.location?.origin).href.replace(/\/$/,'')}
function authReady(){if(!authConfig.apiBase)return false;try{return new URL(authBase()).protocol==='https:'}catch{return false}}
function authEscape(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function authNotice(){if(window.WearQuestFirebase?.googleEnabled)return `<p class="auth-connection" role="note">${authReady()&&authConfig.providers?.includes('kakao')?'Google·카카오'+(authConfig.providers?.includes('naver')?'·네이버':'')+(authConfig.providers?.includes('apple')?'·Apple':''):'Google'}로 로그인할 수 있어요. 아이디·비밀번호로도 가입하고 로그인할 수 있어요.</p>`;return authReady()?'':'<p class="auth-connection" role="note">로그인·회원가입은 인증 서비스 연결 후 이용할 수 있어요. 현재 입력한 정보는 전송하거나 저장하지 않습니다.</p>'}
function authPassword(id,label,auto){return `<label for="${id}">${label}</label><div class="password-field"><input id="${id}" name="${id}" type="password" autocomplete="${auto}" required maxlength="128" placeholder="비밀번호 입력"><button type="button" aria-label="${label} 표시" aria-pressed="false" onclick="togglePassword('${id}',this)">보기</button></div>`}
function togglePassword(id,button){const input=document.getElementById(id),show=input.type==='password';input.type=show?'text':'password';button.textContent=show?'숨기기':'보기';button.setAttribute('aria-pressed',String(show));button.setAttribute('aria-label',show?'비밀번호 숨기기':'비밀번호 표시')}
function socialButtons(){return `<div class="social-grid">${Object.entries(authNames).map(([id,name])=>`<button type="button" class="social-button social-${id}" onclick="startSocial('${id}')"><span class="social-mark" aria-hidden="true"><img src="brand/${id}.svg" alt="" width="24" height="24"></span><span class="social-label">${id==='apple'?'Apple로 로그인':name+'로 로그인'}</span></button>`).join('')}</div><button type="button" class="auth-other" onclick="go('other-login')">기타 로그인 <small>아이디 · 비밀번호</small><span aria-hidden="true">→</span></button>`}
function loginPage(){if(authUser)return accountPage();return `<section class="auth-page auth-methods"><button class="auth-back" onclick="go('home')">← 홈</button><p class="auth-kicker">WEAR QUEST</p><h1>로그인</h1><p class="auth-subtitle">로그인 방법을 선택해주세요.</p>${socialButtons()}<p class="auth-message" id="authMessage" role="status" aria-live="polite"></p>${authNotice()}</section>`}
function signupPage(){return `<section class="auth-page"><button class="auth-back" onclick="go('other-login')">← 로그인</button><p class="auth-kicker">JOIN WEAR QUEST</p><h1>회원가입</h1><p class="auth-subtitle">나만의 계정을 만들어보세요.</p>${authNotice()}<form id="signupForm" onsubmit="submitAuth(event,'signup')"><label for="signupId">아이디</label><input id="signupId" name="username" autocomplete="username" autocapitalize="none" spellcheck="false" required minlength="4" maxlength="20" pattern="[A-Za-z0-9_]{4,20}" placeholder="영문·숫자·밑줄 4~20자" aria-describedby="idHelp"><small id="idHelp" class="auth-help">중복 여부는 가입 시 확인합니다.</small><label for="signupEmail">이메일</label><input id="signupEmail" name="email" type="email" autocomplete="email" required maxlength="254" placeholder="이메일 주소"><label for="signupName">닉네임</label><input id="signupName" name="nickname" autocomplete="nickname" required minlength="2" maxlength="20" placeholder="닉네임 2~20자">${authPassword('signupPassword','비밀번호','new-password')}<small class="auth-help">10~128자 · 다른 서비스와 다른 비밀번호를 사용하세요.</small>${authPassword('signupConfirm','비밀번호 확인','new-password')}<div class="auth-consents"><label><input type="checkbox" id="agreeTerms" required><span>[필수] 이용약관 동의</span><button type="button" onclick="openAuthPolicy('terms')">보기</button></label><label><input type="checkbox" id="agreePrivacy" required><span>[필수] 개인정보 처리방침 확인</span><button type="button" onclick="openAuthPolicy('privacy')">보기</button></label></div><p class="auth-help">현재 약관은 준비 중인 안내문입니다. 정식 가입 전 확정된 약관이 제공됩니다.</p><p class="auth-message" id="authMessage" role="status" aria-live="polite"></p><button class="auth-submit" type="submit">회원가입</button></form><p class="auth-switch">이미 계정이 있으신가요? <button onclick="go('other-login')">로그인</button></p></section>`}
function openAuthPolicy(kind){const panel=document.getElementById('authPolicy');if(panel){panel.remove();return}const section=document.createElement('section');section.id='authPolicy';section.className='auth-policy';section.innerHTML=`<button type="button" onclick="document.getElementById('authPolicy').remove()">안내 닫기 ×</button>${kind==='terms'?termsPage():privacyPage()}`;document.getElementById('signupForm').appendChild(section);section.scrollIntoView({behavior:'smooth',block:'start'})}
function otherLoginPage(){if(authUser)return accountPage();return `<section class="auth-page"><button class="auth-back" onclick="go('login')">← 로그인 방법</button><p class="auth-kicker">WEAR QUEST</p><h1>아이디 로그인</h1><p class="auth-subtitle">아이디와 비밀번호를 입력해주세요.</p>${authNotice()}<form id="loginForm" onsubmit="submitAuth(event,'login')"><label for="loginId">아이디</label><input id="loginId" name="username" autocomplete="username" autocapitalize="none" spellcheck="false" placeholder="아이디 또는 이메일" required maxlength="254">${authPassword('loginPassword','비밀번호','current-password')}<p class="auth-message" id="authMessage" role="status" aria-live="polite"></p><button class="auth-submit" type="submit">로그인</button></form><p class="auth-switch">아직 회원이 아니신가요? <button onclick="go('signup')">회원가입</button></p></section>`}
function authMessage(message,ok=false){const el=document.getElementById('authMessage');if(el){el.textContent=message;el.classList.toggle('success',ok)}else toast(message)}
async function authRequest(path,payload){if(!authReady())throw new Error('인증 서비스 연결 전입니다. 입력한 정보는 전송하거나 저장하지 않았어요.');const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),15000);try{const response=await fetch(authBase()+path,{method:payload?'POST':'GET',credentials:'include',headers:{Accept:'application/json',...(payload?{'Content-Type':'application/json','X-CSRF-Token':authCsrf}:{})},...(payload?{body:JSON.stringify(payload)}:{}),signal:controller.signal});let data;try{data=await response.json()}catch{throw new Error('인증 서버 응답을 확인할 수 없어요. 잠시 후 다시 시도해주세요.')}if(!response.ok){const errors={INVALID_CREDENTIALS:'아이디 또는 비밀번호를 확인해주세요.',USERNAME_TAKEN:'이미 사용 중인 아이디예요.',EMAIL_TAKEN:'이미 가입된 이메일이에요.',RATE_LIMITED:'요청이 많아요. 잠시 후 다시 시도해주세요.',EMAIL_NOT_VERIFIED:'이메일 인증을 완료해주세요.',VALIDATION:'아이디·이메일·비밀번호와 필수 동의 항목을 확인해주세요.',ACCOUNT_UNAVAILABLE:'이용할 수 없는 계정입니다. 고객센터로 문의해주세요.'};throw new Error(errors[data.code]||'요청을 처리하지 못했어요. 잠시 후 다시 시도해주세요.')}return data}finally{clearTimeout(timeout)}}
async function authSession(){const data=await authRequest('/session');authCsrf=typeof data.csrfToken==='string'?data.csrfToken:'';authUser=data.user&&typeof data.user.id==='string'?data.user:null;if(authUser)authBackend='server';return data}
async function submitAuth(event,kind){event.preventDefault();if(authBusy)return;const form=event.currentTarget;if(!form.reportValidity())return;const signup=kind==='signup',password=document.getElementById(signup?'signupPassword':'loginPassword').value;if(signup){if(password.length<10||password.length>128)return authMessage('비밀번호는 10~128자로 입력해주세요.');if(password!==document.getElementById('signupConfirm').value)return authMessage('비밀번호 확인이 일치하지 않아요.');if(document.getElementById('signupName').value.trim().length<2)return authMessage('닉네임은 공백을 제외하고 2자 이상 입력해주세요.')}if(!authReady())return authMessage('인증 서비스 연결 전입니다. 입력한 정보는 전송하거나 저장하지 않았어요.');const button=form.querySelector('[type="submit"]');authBusy=true;button.disabled=true;button.textContent=signup?'가입 처리 중…':'로그인 중…';authMessage('');try{await authSession();if(!authCsrf)throw new Error('인증 세션을 시작하지 못했어요. 다시 시도해주세요.');const payload=signup?{username:document.getElementById('signupId').value.trim(),email:document.getElementById('signupEmail').value.trim(),nickname:document.getElementById('signupName').value.trim(),password,termsAccepted:document.getElementById('agreeTerms').checked,privacyAccepted:document.getElementById('agreePrivacy').checked}:{identifier:document.getElementById('loginId').value.trim(),password};const result=await authRequest(signup?'/register':'/login',payload);form.querySelectorAll('input[type="password"],.password-field input').forEach(input=>input.value='');if(signup)form.reset();{await authSession();if(!authUser)throw new Error('로그인 상태를 확인하지 못했어요. 다시 시도해주세요.');updateAuthHeader();go('account');toast(signup?'회원가입이 완료됐어요.':'로그인됐어요.')}}catch(error){authMessage(error.name==='AbortError'?'응답 시간이 초과됐어요. 다시 시도해주세요.':error instanceof TypeError?'서버에 연결할 수 없어요. 네트워크를 확인해주세요.':error.message)}finally{authBusy=false;button.disabled=false;button.textContent=signup?'회원가입':'로그인'}}
async function startSocial(provider){if(provider==='google'&&window.WearQuestFirebase?.googleEnabled){if(authBusy)return;authBusy=true;authMessage('Google 로그인 중…');try{authUser=await window.WearQuestFirebase.signInGoogle();authBackend='firebase';updateAuthHeader();go('account')}catch(error){authMessage(error.code?window.WearQuestFirebase.errorMessage(error):error.message)}finally{authBusy=false}return;}const allowed=[...(authConfig.providers||[]),...(authConfig.additionalProviders||[]).map(p=>p.id)];if(!authReady())return authMessage(`${authNames[provider]||'SNS'} 로그인 연결 전입니다. 연결 후 이용할 수 있어요.`);if(!allowed.includes(provider)||!/^[a-z0-9-]+$/.test(provider))return authMessage('아직 제공하지 않는 로그인 방식이에요.');if(window.Capacitor?.isNativePlatform?.())return authMessage('앱 내 소셜 로그인은 준비 중입니다. 웹사이트에서 로그인해주세요.');const url=new URL(authBase()+'/oauth/'+provider+'/start');window.location.assign(url.href)}
function accountPage(){if(!authUser)return loginPage();return `<section class="auth-page"><button class="auth-back" onclick="go('home')">← 홈</button><h1>내 계정</h1><div class="auth-account"><b>${authEscape(authUser.nickname||authUser.username||'회원')}</b><p>${authEscape(authUser.email||'')}</p></div><p class="auth-connection">게임·포인트 기록은 현재 기기에 보관됩니다. 계정 동기화는 아직 연결되지 않았어요.</p><button class="auth-submit" onclick="logoutAuth(this)">로그아웃</button><p id="authMessage" class="auth-message" role="status"></p></section>`}
async function logoutAuth(button){button.disabled=true;try{if(authBackend==='server'){if(window.WearQuestFirebase?.configured)await window.WearQuestFirebase.signOut();await authSession();if(!authCsrf)throw new Error('세션을 확인하지 못했어요.');await authRequest('/logout',{});authUser=null;authCsrf='';authBackend='firebase';updateAuthHeader();go('login');return;}if(window.WearQuestFirebase?.configured){await window.WearQuestFirebase.signOut();authUser=null;updateAuthHeader();go('login');return;}await authSession();if(!authCsrf)throw new Error('로그아웃 세션을 확인하지 못했어요.');await authRequest('/logout',{});authUser=null;authCsrf='';updateAuthHeader();go('login')}catch(error){authMessage('로그아웃하지 못했어요. 잠시 후 다시 시도해주세요.');button.disabled=false}}
function updateAuthHeader(){const button=document.querySelector('.header-login');if(button){button.textContent=authUser?'내 계정':'로그인';button.onclick=()=>go(authUser?'account':'login')}}
async function initializeAuth(){
  if(authReady()){
    try{await authSession();if(authUser){updateAuthHeader();if(['login','other-login','account'].includes(route))render();return;}}
    catch{ /* Server failure does not manufacture or overwrite a Google session. */ }
  }
  if(window.WearQuestFirebase?.configured){
    try{await window.WearQuestFirebase.observe(user=>{if(authBackend==='server'&&authUser)return;authUser=user;authBackend='firebase';updateAuthHeader();if(['login','other-login','account'].includes(route))render()},()=>toast('로그인됐지만 프로필을 저장하지 못했어요. 잠시 후 새로고침해주세요.'))}
    catch{toast('로그인 서비스에 연결하지 못했어요. 새로고침 후 다시 시도해주세요.')}
  }
  const error=new URLSearchParams(window.location?.search||'').get('auth_error');
  if(error){const messages={cancelled:'소셜 로그인을 취소했어요.',unavailable:'이용할 수 없는 계정입니다. 고객센터로 문의해주세요.',failed:'소셜 로그인을 완료하지 못했어요. 다시 시도해주세요.'};authMessage(messages[error]||messages.failed);window.history?.replaceState(null,'',window.location.pathname+window.location.hash);}
}
